const fs   = require('fs');
const path = require('path');

let cfg;
try {
  cfg = JSON.parse(fs.readFileSync('/data/notifications/config.json', 'utf8'));
} catch (e) {
  throw new Error('Cannot read /data/notifications/config.json');
}

if (cfg.telegram_bot_token === 'YOUR_BOT_TOKEN_HERE') {
  throw new Error('Please set telegram_bot_token in notifications/config.json');
}

// ── Helpers ──────────────────────────────────────────────────
const today = new Date().toLocaleDateString('en-IN', {
  timeZone: cfg.timezone || 'Asia/Kolkata',
  day: '2-digit', month: 'short', year: 'numeric'
});

function countTodayFiles(dir, ext) {
  if (!fs.existsSync(dir)) return 0;
  const cutoff = new Date(); cutoff.setHours(0, 0, 0, 0);
  let count = 0;
  function walk(d) {
    fs.readdirSync(d).forEach(f => {
      const full = path.join(d, f);
      const stat = fs.statSync(full);
      if (stat.isDirectory()) walk(full);
      else if (stat.mtimeMs >= cutoff && (!ext || f.endsWith(ext))) count++;
    });
  }
  walk(dir);
  return count;
}

function countTodayFolders(dir) {
  if (!fs.existsSync(dir)) return 0;
  const cutoff = new Date(); cutoff.setHours(0, 0, 0, 0);
  return fs.readdirSync(dir)
    .filter(f => {
      const s = fs.statSync(path.join(dir, f));
      return s.isDirectory() && s.mtimeMs >= cutoff;
    }).length;
}

// ── Count today's output ─────────────────────────────────────
const contentFiles  = countTodayFiles('/data/content/output', '.md');
const mediaRuns     = countTodayFolders('/data/media/output');
const wallpaperFiles= countTodayFiles('/data/wallpaper/output', '.png') +
                      countTodayFiles('/data/wallpaper/output', '.jpg');

const total = contentFiles + mediaRuns + wallpaperFiles;

// ── Build message ─────────────────────────────────────────────
const lines = [
  `📊 <b>Daily Summary — ${today}</b>`,
  ``,
];

if (total === 0) {
  lines.push(`😴 Nothing was generated today.`);
} else {
  lines.push(`✅ <b>${total} item(s) generated today</b>`, ``);
  if (contentFiles  > 0) lines.push(`📝 Content files:   <b>${contentFiles}</b>`);
  if (mediaRuns     > 0) lines.push(`🖼️  Media batches:   <b>${mediaRuns}</b>`);
  if (wallpaperFiles> 0) lines.push(`🖼️  Wallpapers:      <b>${wallpaperFiles}</b>`);
}

lines.push(``, `<i>— ${cfg.project_name || 'Automate Hub'}</i>`);

return [{
  json: {
    token:   cfg.telegram_bot_token,
    chat_id: cfg.telegram_chat_id,
    message: lines.join('\n')
  }
}];
